import { LANG_STRINGS } from '../../../lang'

export const provinceCityDataForm = (data = {}, showBorder = false, skipEmptyCheck = false, labels = {}) => {
  return {
    fields: [
      {
        type: 'autoSearchModal',
        placeholder: labels.province ? labels.province : LANG_STRINGS.selectProvince,
        name: 'province_code',
        data: data.provinces,
        label: labels.province ? labels.province : LANG_STRINGS.selectProvince,
        dataKey: 'province_code',
        displayKey: 'province_name',
        defaultValue: data.province_code,
        defaultData: data.province_code_data,
        border: showBorder,
        skipEmptyCheck
      },
      {
        type: 'autoSearchModal',
        placeholder: labels.city ? labels.city : LANG_STRINGS.selectCity,
        name: 'city_code',
        data: data.cities,
        label: labels.city ? labels.city : LANG_STRINGS.selectCity,
        dataKey: 'city_code',
        displayKey: 'city_name',
        ref: data.citiesRef,
        defaultValue: data.city_code,
        defaultData: data.city_code_data,
        border: showBorder,
        skipEmptyCheck
      }
    ]
  }
}
