import { useCallback, useRef, useState } from 'react'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import CustomText from '../../CustomText'
import DobInput from '../../DobInput'
import moment from 'moment'
import { PolicyStartDateStyle } from './index.style'
import TitleError from '../../TitleError'

function PolicyStartDate (props) {
  const { onUpdateStartDate, policyStartDate, startDateError } = props
  const [state, setState] = useState({
    startDateDefaultValue: moment(policyStartDate, 'YYYY-MM-DD').format('DD/MM/YYYY'),
    policyEndDate: moment(policyStartDate, 'YYYY-MM-DD').add(1, 'year').format('DD/MM/YYYY')
  })
  const dateRef = useRef()
  const handleDateSelect = useCallback((startDate) => {
    const endDate = (startDate && moment(startDate, 'DD/MM/YYYY', true)) || {}
    const policyEndDate = endDate._isValid && (moment(startDate, 'DD/MM/YYYY').add(1, 'year').format('DD/MM/YYYY'))

    setState({
      startDate,
      policyEndDate,
      startDateReqError: ''
    })

    if (onUpdateStartDate) {
      onUpdateStartDate({
        startDate: (!dateRef.current.state.showError && endDate._isValid) && moment(startDate, 'DD/MM/YYYY').format('YYYY-MM-DD'),
        policyEndDate
      })
    }
  }, [onUpdateStartDate])

  return (
    <CollapsibleCard title={LANG_STRINGS.policyDetail} isOpen>
      <PolicyStartDateStyle>
        <TitleError
          required
          weight={700}
          size='10px'
          title={LANG_STRINGS.policyStartDate}
          error={!!startDateError && LANG_STRINGS.required}
        />
        <DobInput
          errorField={startDateError}
          name='selectStartDate'
          showCalenderIcon
          onDobSelect={handleDateSelect}
          minDate={new Date(moment(policyStartDate, 'YYYY-MM-DD'))}
          maxDate={moment(Date.now()).add(30, 'day')._d}
          ref={dateRef}
          displayBorder
          borderColor={AgentColorPallette.Gray90}
          defaultValue={state.startDateDefaultValue}
          placeholder={LANG_STRINGS.enterPolicyStartDate}
        />
        {
          state.policyEndDate && (
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              size='10px'
              className='policy-end-date'
            >
              {LANG_STRINGS.policyWillExpire.replace('XXX', state.policyEndDate)}
            </CustomText>
          )
        }
      </PolicyStartDateStyle>
    </CollapsibleCard>
  )
}

export default PolicyStartDate
