import { useCallback, useState } from 'react'
import { CustomText, Upload } from '../..'
import { Row } from '../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import { PolicyVehicleImgStyle } from './index.style'

function PolicyVehicleImg (props) {
  const { images = {}, onUpdateVehicleImg } = props
  const [errorImages] = useState({})

  const getTitle = useCallback((title) => (
    <CustomText
      color={AgentColorPallette.darkCharcoal}
      size='10px'
      bottom='3px'
      weight={700}
    >
      {title}
    </CustomText>
  ), [])

  const getRowImageContainer = useCallback(({
    title, img, type, errorImages,
    width, labelAlign, className
  }) => {
    return (
      <div className={className}>
        {
          getTitle(title, type)
        }
        <Upload
          hideLabel
          displayBorder
          className='upload-wrapper'
          label={title}
          width={width}
          name={type}
          labelAlign={labelAlign}
          defaultValue={img}
          showImg
          onUpload={(data) => onUpdateVehicleImg(data, 'images')}
          errorField={errorImages && !img && type}
        />
      </div>
    )
  }, [getTitle, onUpdateVehicleImg])

  return (
    <CollapsibleCard title={LANG_STRINGS.photoInsuredObject} isOpen>
      <PolicyVehicleImgStyle>
        {/* title, img, type, errorImages,
    width, labelAlign, invert = false, className */}
        {
          getRowImageContainer({
            title: LANG_STRINGS.dashboard,
            img: images.dashboard,
            type: 'dashboard',
            errorImages
          })
        }
        <Row justify='space-between' align='center'>
          {
            getRowImageContainer({
              title: LANG_STRINGS.frontLook,
              img: images.front,
              type: 'front',
              errorImages,
              width: '100%',
              className: 'small-img-wrapper'
            })
          }
          {
            getRowImageContainer({
              title: LANG_STRINGS.backView,
              img: images.back,
              type: 'back',
              errorImages,
              width: '100%',
              className: 'small-img-wrapper'
            })
          }
        </Row>
        <Row justify='space-between' align='center'>
          {
            getRowImageContainer({
              title: LANG_STRINGS.leftSide,
              img: images.left,
              type: 'left',
              errorImages,
              width: '100%',
              className: 'small-img-wrapper'
            })
          }
          {
            getRowImageContainer({
              title: LANG_STRINGS.toTheRightSide,
              img: images.right,
              type: 'right',
              errorImages,
              width: '100%',
              className: 'small-img-wrapper'
            })
          }
        </Row>
      </PolicyVehicleImgStyle>
    </CollapsibleCard>
  )
}

export default PolicyVehicleImg
