import { Component } from 'react'
import PropTypes from 'prop-types'
import { BuildingImgStyle } from './index.style'
import { Row } from '../../../../../commonStyle/index.style'
import BuildImgUpload from '../BuildImgUpload'
import { BUILDING_IMGS_COUNT } from '../../constants'
import TitleError from '../../../../../components/TitleError'

class BuildingImgSection extends Component {
  static propTypes = {
    title: PropTypes.string,
    className: PropTypes.string,
    titleClassName: PropTypes.string,
    type: PropTypes.string,
    error: PropTypes.string,
    defaultImgs: PropTypes.object,
    images: PropTypes.object,
    onSaved: PropTypes.func
  }

  handleToSaveImg = (type, img) => {
    if (img) {
      this.props.images[type] = img
    } else {
      delete this.props.images[type]
    }

    if (this.props.onSaved) {
      this.props.onSaved(this.props.images, this.props.type)
    }
  }

  render () {
    const { title, type, error, defaultImgs = {}, className, titleClassName } = this.props
    return (
      <BuildingImgStyle>
        <TitleError
          title={title}
          titleClassName={titleClassName}
          error={error}
        />
        <Row justify='space-between' align='center'>
          {
            BUILDING_IMGS_COUNT.map((imgCount, index) =>
              <BuildImgUpload
                title={title}
                className={className}
                key={`${title}_${imgCount.type}`}
                name={`${type}_${imgCount.type}`}
                index={index}
                defaultImg={defaultImgs[`image_${index + 1}`]}
                onUpload={this.handleToSaveImg}
              />
            )
          }
        </Row>
      </BuildingImgStyle>
    )
  }
}

export default BuildingImgSection
