import { useErrorContextValue, useLoaderContextValue, resetError, updateLoader } from '@pasarpolis/common-react-hooks'
import find from 'lodash/find'
import get from 'lodash/get'
import isEmpty from 'lodash/isEmpty'
import { useMemo, useEffect, useCallback, useRef, useState } from 'react'
import { BottomActionContainerStyle } from '../../../../../../commonStyle/index.style'
import { Container } from '../../../../../../components'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import PolicyCertificateAndAppointment from '../../../../../../components/PolicyComponents/PolicyCertificateAndAppointment'
import PolicyCustomerData from '../../../../../../components/PolicyComponents/PolicyCustomerData'
import PolicyHardCopy from '../../../../../../components/PolicyComponents/PolicyHardCopy'
import PolicyPropertyData from '../../../../../../components/PolicyComponents/PolicyPropertyData'
import PolicyPropertyImg from '../../../../../../components/PolicyComponents/PolicyPropertyImg'
import PolicyStartDate from '../../../../../../components/PolicyComponents/PolicyStartDate'
import PolicyVehicleData from '../../../../../../components/PolicyComponents/PolicyVehicleData'
import PolicyVehicleImg from '../../../../../../components/PolicyComponents/PolicyVehicleImg'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { TRANSACTION_EDIT_SUCCESS } from '../../../../../../constants/cookies'
import { CAR_PROTECTION, RENEW_OTHER_PURCHASE, RENEW_PURCHASE } from '../../../../../../constants/pkgCode'
import { setToLocalStorage } from '../../../../../../helpers/localstorage'
import { CHECK_GOLD } from '../../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'
import { useEditUpdateQuotation } from '../../../state/hooks/usePolicyState'
import { PolicyDataChangeStyle } from './index.style'

function PolicyDataChangeContainer (props) {
  const { location, history, match } = props
  // get the policyId and application data from the url
  const policyId = useMemo(() => match.params.policyId, [match])
  const applicationData = useMemo(
    () => ((location.state && location.state.applicationDetail) || {}), [location.state]
  )
  const policyDetails = useMemo(() => applicationData.policy_detail || {}, [applicationData.policy_detail])
  const isRenewalOther = useMemo(
    () => [RENEW_OTHER_PURCHASE, RENEW_PURCHASE].includes(policyDetails.purchase_type),
    [policyDetails.purchase_type]
  )
  const isMVProduct = useMemo(() => (
    get(applicationData.product, 'package.product.code', '') === CAR_PROTECTION),
  [applicationData.product]
  )
  const [{ GET_CITIES_LOADER, UPDATE_QUOTATION_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ updateQuotationStatus }, dispatchError] = useErrorContextValue()
  const [errorMap, setErrorMap] = useState({})
  const [snackbarMap, setSnackbarMap] = useState({
    show: false,
    error: false
  })

  const [, editUpdateRequest] = useEditUpdateQuotation()
  const customerRef = useRef(null)
  const customerAddressProvinceCityRef = useRef(null)
  const customerAddressRef = useRef(null)
  const vehicleRef = useRef(null)
  const hardCopyRef = useRef(null)
  let provCitySubmit = () => {}
  // initial Data setup
  const that = useRef({
    startDate: policyDetails.start_date,
    images: isMVProduct ? policyDetails.images : {
      front_look: {
        ...policyDetails.front_look
      },
      left_building: {
        ...policyDetails.left_building
      },
      right_building: {
        ...policyDetails.right_building
      },
      in_building: {
        ...policyDetails.in_building
      }
    },
    ...(isMVProduct && !policyDetails.photo_required ? {
      previous_certificate_url: policyDetails.previous_certificate_url,
      appointment_letter_url: policyDetails.appointment_letter_url
    } : {}
    ),
    propertyAddress: policyDetails.property_address,
    vehicleData: {
      regionCode: policyDetails.region_code,
      vehiclePlateNo: policyDetails.vehicle_plate_no
    }
  })

  const updateSnackBar = useCallback((text, error) => {
    setSnackbarMap({
      error,
      show: true,
      msg: text
    })
    setTimeout(() => {
      setSnackbarMap({
        show: false
      })
    }, 2000)
  }, [])

  useEffect(() => {
    function resetUpdateStatus () {
      dispatchError(resetError({
        updateQuotationStatus: undefined
      }))
    }

    function goToTransactionDetail () {
      history.push({
        pathname: `/transactions/${policyId}/details`
      })
    }
    if (!applicationData.id) {
      // if application id not exist then back
      // to transaction detail page
      goToTransactionDetail()
    }
    if (updateQuotationStatus === 'success') {
      // handle the to back to transaction details
      setToLocalStorage(TRANSACTION_EDIT_SUCCESS, 'success')
      goToTransactionDetail()
      resetUpdateStatus()
    } else if (updateQuotationStatus) {
      updateSnackBar(updateQuotationStatus, true)
      resetUpdateStatus()
    }
  }, [
    applicationData, policyId, history,
    updateQuotationStatus, dispatchError,
    updateSnackBar
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_PROVINCE_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleStartDate = useCallback((data) => {
    that.current = {
      ...that.current,
      ...data
    }
  }, [])

  const handleApplicationDataChange = useCallback((data, type) => {
    const { current } = that
    switch (type) {
      case 'images': {
        that.current = {
          ...current,
          [type]: {
            ...(current.images),
            ...data
          }
        }
        return
      }
      default: {
        that.current = {
          ...current,
          [type]: data
        }
        break
      }
    }
  }, [])

  const handleProvinceCitySubmit = (provCityOnSubmit) => {
    provCitySubmit = provCityOnSubmit
  }

  const handleSave = useCallback(async (e) => {
    // handle the save data changes
    const customerData = await customerRef.current.handleSubmit(e)
    if (!customerData) return
    let isValidData = true
    const error = {}
    let vehicleData = {}
    let hardCopyData = {}
    let softCopyAddress = {}
    let address = ''
    let custProvCode = ''; let custCityCode = ''; let custZipCode = ''; let custAddrDetail = ''
    const custAddRequired = get(applicationData, 'product.extra_details.customer_address_required', false)
    let custProvName = ''; let custCityName = ''; let custRegion = ''

    if (custAddRequired) {
      const custProvCity = await provCitySubmit(e)
      const custAddrData = await customerAddressRef.current.handleSubmit(e)
      if (!custProvCity || !custAddrData) {
        return
      }
      custProvCode = get(custProvCity, 'province_code', '')
      custCityCode = get(custProvCity, 'city_code', '')
      custProvName = get(custProvCity, 'province_name', '')
      custCityName = get(custProvCity, 'city_name', '')
      custRegion = get(custProvCity, 'region', '')
      custZipCode = get(custAddrData, 'postal_code', '')
      custAddrDetail = get(custAddrData, 'customer_address_detail', '')
    }
    if (vehicleRef.current) {
      vehicleData = await vehicleRef.current.handleSubmit(e)
    }

    if (!vehicleData) {
      isValidData = false
    }
    if (hardCopyRef.current) {
      hardCopyData = await hardCopyRef.current.handleSubmit(e)
      if (hardCopyData) {
        if (hardCopyData.isprovince_codeDefault) {
          const cityData = find(that.current.cities, { city_code: hardCopyData.city_code })
          const province = find(that.current.provinces, { province_code: hardCopyData.province_code })
          softCopyAddress = {
            ...cityData,
            ...province,
            postal_code: hardCopyData.postal_code,
            address: hardCopyData.address
          }
        } else {
          address = hardCopyData.address
        }
      } else {
        isValidData = false
      }
    }

    if (!that.current.startDate) {
      isValidData = false
      error.startDateError = 'selectStartDate'
    }

    if (isMVProduct) {
      if (!that.current.vehicleData.regionCode) {
        isValidData = false
        error.errorRegionCode = true
      }

      if (!that.current.vehicleData.vehiclePlateNo) {
        isValidData = false
        error.errorPlateNo = true
      }
    } else {
      const { images = {} } = that.current
      if (!that.current.propertyAddress) {
        isValidData = false
        error.propertyAddressError = true
      }
      for (const key in images) {
        if (isEmpty(images[key])) {
          isValidData = false
          error[`${key}`] = true
        }
      }
    }

    if (isRenewalOther && !policyDetails.isPhotoRequired && !that.current.previous_certificate_url) {
      error.certificate = true
      isValidData = false
    }

    if (!isValidData) {
      setErrorMap(error)
      updateSnackBar(ERROR_LANG.pleaseProvideAllRequiredData, true)
      return
    }
    let otherDoc = {}

    if (isRenewalOther && that.current.previous_certificate_url) {
      otherDoc = {
        previous_certificate_url: that.current.previous_certificate_url,
        appointment_letter_url: that.current.appointment_letter_url
      }
    } else if (policyDetails.photo_required) {
      otherDoc.images = that.current.images
    }

    let body = {
      address,
      start_date: that.current.startDate,
      ktp_no: `${customerData.ktp_no}`,
      ktp_url: typeof customerData.ktp === 'string' ? customerData.ktp : customerData.ktp.ktp,
      code: applicationData.code,
      customer_data: {
        name: customerData.name,
        email: customerData.email,
        mobile_no: customerData.mobile_no,
        customer_address: {
          province_code: custProvCode,
          province_name: custProvName,
          city_code: custCityCode,
          city_name: custCityName,
          region: custRegion,
          postal_code: custZipCode,
          address: custAddrDetail
        }
      }
    }
    if (isMVProduct) {
      body = {
        ...body,
        ...otherDoc,
        chasis_number: policyDetails.chasis_number,
        machine_number: policyDetails.machine_number,
        color: vehicleData.color,
        stnk_url: typeof vehicleData.stnk_url === 'string' ? vehicleData.stnk_url : vehicleData.stnk_url.stnk_url,
        region_code: that.current.vehicleData.regionCode,
        transmission_type: policyDetails.transmission_type,
        vehicle_plate_no: that.current.vehicleData.vehiclePlateNo
      }
    } else {
      body = {
        ...body,
        property_address: that.current.propertyAddress,
        ...(that.current.images || {}),
        hard_copy_address: softCopyAddress
      }
    }
    editUpdateRequest({
      body,
      policyId
    })
  }, [
    editUpdateRequest, policyId, applicationData, isRenewalOther,
    policyDetails, isMVProduct, updateSnackBar
  ])

  return (
    <Container
      hideBottomTabs
      title={LANG_STRINGS.changePolicyData}
      loader={GET_CITIES_LOADER || UPDATE_QUOTATION_LOADER}
    >
      <PolicyDataChangeStyle>
        <PolicyStartDate
          policyStartDate={policyDetails.start_date}
          onUpdateStartDate={handleStartDate}
          startDateError={errorMap.startDateError}
        />
        <PolicyCustomerData
          onProvinceCitySubmit={handleProvinceCitySubmit}
          applicationData={applicationData}
          isMVApplication={isMVProduct}
          customerRef={customerRef}
          customerAddressRef={customerAddressRef}
          customerAddressProvinceCityRef={customerAddressProvinceCityRef}
          onUpdateCustomerData={handleApplicationDataChange}
        />
        {
          isMVProduct && (
            <>
              <PolicyVehicleData
                data={policyDetails}
                vehicleRef={vehicleRef}
                errorPlateNo={errorMap.errorPlateNo}
                errorRegionCode={errorMap.errorRegionCode}
                onUpdateVehicleData={handleApplicationDataChange}
              />
              {
                policyDetails.photo_required && (
                  <PolicyVehicleImg
                    images={policyDetails.images}
                    onUpdateVehicleImg={handleApplicationDataChange}
                  />
                )
              }
              {
                isRenewalOther && (
                  <PolicyCertificateAndAppointment
                    isPhotoRequired={policyDetails.photo_required}
                    isRenewalOther={isRenewalOther}
                    error={errorMap}
                    previousCertificateUrl={policyDetails.previous_certificate_url}
                    appointmentLetterUrl={policyDetails.appointment_letter_url}
                    onUpdate={handleApplicationDataChange}
                  />
                )
              }
            </>
          )
        }
        {
          !isMVProduct && (
            <>
              <PolicyPropertyData
                policyDetails={policyDetails}
                errorField={errorMap.propertyAddressError}
                onUpdateLocation={handleApplicationDataChange}
              />
              <PolicyPropertyImg
                images={that.current.images}
                error={errorMap}
                onUpdatePropertyImg={handleApplicationDataChange}
              />
            </>
          )
        }
        {
          policyDetails.hard_copy_required && (
            <PolicyHardCopy
              applicationData={applicationData}
              isMVProduct={isMVProduct}
              hardCopyRef={hardCopyRef}
              onUpdatePolicyHardCopy={handleApplicationDataChange}
            />
          )
        }
        <BottomActionContainerStyle padding='0'>
          <ButtonWithIcon
            text={LANG_STRINGS.saveChanges}
            icon={CHECK_GOLD}
            iconRight
            className='bottom-btn'
            onClick={handleSave}
          />
        </BottomActionContainerStyle>
      </PolicyDataChangeStyle>
      {
        snackbarMap.show && (
          <ShowSnackbar
            show={snackbarMap.show}
            text={snackbarMap.msg}
            error={snackbarMap.error}
          />
        )
      }
    </Container>
  )
}

export default PolicyDataChangeContainer
