import { Component } from 'react'
import PropTypes from 'prop-types'
import { CAMERA_GREY, SEARCH } from '../../../../../images'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import { BuildImgUploadStyle, BuildingUploadImg } from './index.style'
import PolicyActions from '../../../../../redux/policy/action'
import LoadingActions from '../../../../../redux/loading/action'
import ErrorActions from '../../../../../redux/error/action'
import { connect } from 'react-redux'
import CircularLoader from '../../../../../components/CircularLoader'
import ZoomEditImg from '../../../../../components/ZoomEditImgModal'
import { INPUT_FILE_TYPE } from '../../../../../constants/file'

const { getUploadLink, resetPolicyStore } = PolicyActions
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions
class BuildImgUpload extends Component {
  static propTypes = {
    title: PropTypes.string,
    name: PropTypes.string,
    defaultImg: PropTypes.string,
    index: PropTypes.number,
    onUpload: PropTypes.func,
  }

  state = {
    [this.props.name]: this.props.defaultImg,
    name: '',
    showModal: false,
  }

  componentDidMount() {
    const { name, index } = this.props
    if (this.state[name]) {
      this.props.onUpload(`image_${index + 1}`, this.state[name])
    }
  }

  componentDidUpdate() {
    const { getUploadLinkError, getUploadLinkLoading, uploadLink } = this.props
    const { name, resetPolicyStore, index } = this.props
    if (getUploadLinkError && getUploadLinkLoading === false) {
      this.props.resetErrorRedux(['GET_UPLOAD_LINK'])
      this.props.resetLoadingRedux(['GET_UPLOAD_LINK'])
    }
    if (uploadLink[name]) {
      const imgUrl = uploadLink[name].url
      if (this.state.name === name) {
        if (this.props.onUpload) {
          this.props.onUpload(`image_${index + 1}`, imgUrl)
        }
        this.setState({
          [name]: imgUrl,
          name: '',
        })
      }
      resetPolicyStore(['uploadLink'])
      this.props.resetErrorRedux(['GET_UPLOAD_LINK'])
      this.props.resetLoadingRedux(['GET_UPLOAD_LINK'])
    }
  }

  handleUpload = (e, inputName) => {
    // e.preventDefault()
    // inputName passed by the zoom modal input change method
    const { name } = this.props
    const file = document.getElementById(inputName || name)
    if ('files' in file) {
      if (file.files[0]) {
        if (file.files[0].size > 11000000) {
          NotificationManager.error('Ukuran file terlalu besar')
        } else {
          NotificationManager.info('Pengunggahan dimulai')
          this.setState({
            name,
            showModal: false,
          })
          this.props.getUploadLink({ file: file.files[0], name: name })
        }
      }
    }
  }

  handleShowModal = () => {
    this.setState({
      showModal: true,
    })
  }

  handleCloseModal = () => {
    this.setState({
      showModal: false,
    })
  }

  handleRemoveImg = () => {
    // handle the img remove
    const { name, index } = this.props
    this.setState(
      {
        [name]: '',
        showModal: false, // remove the img from the name field
      },
      () => {
        this.props.onUpload(`image_${index + 1}`, '')
      }
    )
  }

  render() {
    const { name, fileType, getUploadLinkLoading, title, className } = this.props
    const { showModal } = this.state
    const stateUpdated = this.state.name === name
    const imgUrl = this.state[name]

    return (
      <BuildImgUploadStyle className={className}>
        <CircularLoader isLoading={getUploadLinkLoading && stateUpdated}>
          {imgUrl ? (
            <BuildingUploadImg url={imgUrl} onClick={this.handleShowModal}>
              <div className="zoom-img">
                <img src={SEARCH} width="9px" alt="zoom" />
              </div>
            </BuildingUploadImg>
          ) : (
            <div className="img-empty-container">
              <img src={CAMERA_GREY} alt="" />
              <input
                className="input-file"
                type="file"
                id={name}
                name={name}
                onChange={this.handleUpload}
                accept={fileType || INPUT_FILE_TYPE.IMAGE}
              />
            </div>
          )}
        </CircularLoader>
        {showModal && (
          <ZoomEditImg
            showModal={showModal}
            title={title}
            imgUrl={imgUrl}
            name={name}
            onClose={this.handleCloseModal}
            onChangeImg={this.handleUpload}
            onRemoveImg={this.handleRemoveImg}
          />
        )}
        <NotificationContainer />
      </BuildImgUploadStyle>
    )
  }
}

export default connect(
  (state) => ({
    getUploadLinkLoading: state.Loading.GET_UPLOAD_LINK,
    getUploadLinkError: state.Error.GET_UPLOAD_LINK,
    uploadLink: state.Policy.uploadLink,
  }),
  {
    getUploadLink,
    resetErrorRedux,
    resetPolicyStore,
    resetLoadingRedux,
  }
)(BuildImgUpload)
