import get from 'lodash/get'
import { useCallback, useEffect, useMemo, useRef } from 'react'
import { InnerForm } from '../..'
import { useProvinceCityData } from '../../../containers/Private/Policy/state/hooks/usePolicyState'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import { getHardCopyAddressData } from '../helper'
import { PolicyHardCardStyle } from './index.style'

function PolicyHardCopy (props) {
  const { applicationData = {}, isMVProduct, hardCopyRef, onUpdatePolicyHardCopy } = props
  const citiesRef = useRef()
  const {
    getProvinceData, getCitiesData, handleProvinceSelect
  } = useProvinceCityData(citiesRef, isMVProduct, get(applicationData, 'policy_detail.province_code', ''))

  useEffect(() => {
    onUpdatePolicyHardCopy(getProvinceData, 'provinces')
    onUpdatePolicyHardCopy(getCitiesData, 'cities')
  }, [onUpdatePolicyHardCopy, getProvinceData, getCitiesData])

  const hardCopyData = useMemo(() => getHardCopyAddressData({
    ...applicationData,
    provinces: getProvinceData || [],
    cities: getCitiesData || [],
    isMVApplication: isMVProduct,
    citiesRef
  }, {
    border: true,
    className: 'remove-box-shadow',
    autoSearchInputClass: 'auto-search-input'
  }), [
    getProvinceData, getCitiesData, isMVProduct, applicationData
  ])

  const handleSelectChange = useCallback((value) => {
    if (value.province_code) {
      handleProvinceSelect(value.province_code)
    }
  }, [handleProvinceSelect])

  return (
    <CollapsibleCard title={LANG_STRINGS.printPolicy} isOpen>
      <PolicyHardCardStyle>
        <InnerForm
          formData={hardCopyData}
          ref={hardCopyRef}
          titleClassName='form-title'
          onChangeSelect={handleSelectChange}
        />
      </PolicyHardCardStyle>
    </CollapsibleCard>
  )
}

export default PolicyHardCopy
