import { size } from 'lodash'
import find from 'lodash/find'
import get from 'lodash/get'
import { forwardRef, useEffect, useRef, useCallback } from 'react'
import { connect } from 'react-redux'
import { PROPERTY_PROVINCE_CITY } from '../../constants/cookies'
import { getFromLocalStorageData } from '../../helpers/localstorage'
import propertyActions from '../../redux/property/actions'
import InnerForm from '../InnerForm'
import { provinceCityDataForm } from './helper'

const { getPropertyProvince, getPropertyCities } = propertyActions

function ProvinceCityDropDown (props, ref) {
  // here we are handling the city and Province
  const {
    getPropertyProvince, getPropertyCities, provinces,
    propertyCities, defaultData = {}, showBorder = false,
    skipEmptyCheck = false, titleClassName = '',
    onProvinceCitySubmit, labels = {}
  } = props
  const preFormData = getFromLocalStorageData(PROPERTY_PROVINCE_CITY) || {}
  const citiesRef = useRef(null)
  const provinceForm = provinceCityDataForm()
  provinceForm.fields[1].ref = citiesRef
  const citiesDataRef = useRef(null)
  const redundencyMaintainer = useRef(true)

  // setProvinceFormState
  useEffect(() => {
    if (defaultData.province_code) {
      getPropertyProvince()
      getPropertyCities(defaultData.province_code)
    } else {
      getPropertyProvince()
    }
  }, [getPropertyProvince, getPropertyCities, defaultData.province_code])

  useEffect(() => {
    if (size(propertyCities) && redundencyMaintainer.current) {
      redundencyMaintainer.current = false
      citiesDataRef.current = propertyCities
    }
  }, [propertyCities,
    citiesDataRef,
    redundencyMaintainer
  ])

  const handleSelectChange = (value) => {
    // data from the autoSearch
    if (value.province_code) {
      redundencyMaintainer.current = true
      getPropertyCities(value.province_code)
      if (citiesRef.current) {
        citiesRef.current.resetModalState()
      }
    }
  }

  const onSubmit = useCallback(async (e) => {
    const data = {}
    const provCityData = await ref.current.handleSubmit(e)
    if (!provCityData) {
      return
    }
    data.province_code = get(provCityData, 'province_code', '')
    data.province_name = find(props.provinces, { province_code: data.province_code }).province_name
    data.city_code = get(provCityData, 'city_code')
    const citydata = find(citiesDataRef.current, { city_code: data.city_code }) || {}
    data.city_name = citydata.city_name
    data.region = citydata.region
    return {
      ...data
    }
  }, [ref, props.provinces,
    citiesDataRef
  ])

  useEffect(() => {
    if (onProvinceCitySubmit) {
      onProvinceCitySubmit(onSubmit)
    }
  }, [onProvinceCitySubmit, onSubmit])

  return (
    <>
      {
        !!size(provinces) && (
          <InnerForm
            formData={provinceCityDataForm({
              ...defaultData,
              ...preFormData,
              cities: size(citiesDataRef.current) ? citiesDataRef.current : preFormData.cities,
              provinces: provinces,
              citiesRef
            }, showBorder, skipEmptyCheck, labels)}
            onChangeSelect={handleSelectChange}
            ref={ref}
            titleClassName={titleClassName}
          />
        )
      }
    </>
  )
}

export default connect(
  state => ({
    provinces: state.Property.provinces,
    provincesStatus: state.Property.provincesStatus,
    propertyCities: state.Property.propertyCities,
    propertyCitiesStatus: state.Property.propertyCitiesStatus,

    provincesLoader: state.Loading.GET_PROPERTY_PROVINCE,
    citiesLoader: state.Loading.GET_PROPERTY_CITIES
  }),
  {
    getPropertyProvince,
    getPropertyCities
  },
  null,
  {
    forwardRef: true
  }
)(forwardRef(ProvinceCityDropDown))
