import isEmpty from 'lodash/isEmpty'
import { useCallback, useMemo, useState } from 'react'
import { InnerForm } from '../..'
import { Row } from '../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { RENEW_PURCHASE } from '../../../constants/pkgCode'
import { APPLICATION_LANG } from '../../../containers/Private/Application/lang'
import { typeValid } from '../../../helpers/validations'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import CustomText from '../../CustomText'
import InnerInput from '../../InnerInput'
import TitleError from '../../TitleError'
import { getVehicleData } from '../helper'
import { PolicyVehicleDataStyle } from './index.style'

function PolicyVehicleData (props) {
  const { data = {}, vehicleRef, onUpdateVehicleData, errorPlateNo, errorRegionCode } = props
  const [vehicleState, setVehicleState] = useState({
    regionCode: data.region_code
  })
  const formData = useMemo(() => getVehicleData(data), [data])
  const isPlatNumberError = useMemo(() => (
    ((vehicleState.vehiclePlateNo === '' || !typeValid('plate_no', vehicleState.vehiclePlateNo)) && vehicleState.errorPlateNo) || errorPlateNo ? 'vehicle_plate_no' : ''
  ), [vehicleState, errorPlateNo])

  const handlePlateRegionNumber = useCallback((value, type) => {
    setVehicleState((vehicleState) => {
      const data = {
        ...vehicleState,
        [type]: value,
        errorPlateNo: false
      }
      onUpdateVehicleData(data, 'vehicleData')
      return data
    })
  }, [onUpdateVehicleData])

  return (
    <CollapsibleCard title={LANG_STRINGS.insuredObject} isOpen>
      <PolicyVehicleDataStyle>
        <TitleError
          required
          weight={700}
          size='10px'
          title={LANG_STRINGS.plateNumber}
          error={(errorPlateNo || errorRegionCode) && LANG_STRINGS.required}
        />
        <Row>
          <CustomText
            color={AgentColorPallette.black}
            className='region-codes'
          >
            {data.region_code}
          </CustomText>
          <InnerInput
            errorField={isPlatNumberError}
            name='vehicle_plate_no'
            value={vehicleState.vehiclePlateNo}
            placeholder={APPLICATION_LANG.vehiclePlaceHolder}
            defaultValue={isEmpty(data) ? null : data.vehicle_plate_no}
            onChange={e => handlePlateRegionNumber(e.target.value, 'vehiclePlateNo')}
            disabled={data.purchase_type === RENEW_PURCHASE}
            displayBorder
            className='remove-box-shadow'
          />
        </Row>
        <InnerForm
          formData={formData}
          ref={vehicleRef}
          titleClassName='form-title'
        />
      </PolicyVehicleDataStyle>
    </CollapsibleCard>
  )
}

export default PolicyVehicleData
