import { useCallback } from 'react'
import BuildingImgSection from '../../../containers/CommonContainer/PropertyDetailForm/components/BuildingImgSection'
import { BUILDING_IMGS } from '../../../containers/CommonContainer/PropertyDetailForm/constants'
import { ERROR_LANG, LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import { PolicyPropertyImgStyle } from './index.style'

function PolicyPropertyImg (props) {
  const { images = {}, error = {}, onUpdatePropertyImg } = props

  const handleSavedImgs = useCallback((img, type) => {
    onUpdatePropertyImg({
      [type]: img
    }, 'images')
  }, [onUpdatePropertyImg])

  return (
    <CollapsibleCard title={LANG_STRINGS.photoInsuredObject} isOpen>
      <PolicyPropertyImgStyle>
        {
          BUILDING_IMGS.map(imgSection => (
            <BuildingImgSection
              key={imgSection.type}
              title={imgSection.title}
              type={imgSection.type}
              defaultImgs={images[imgSection.type]}
              images={imgSection.images}
              onSaved={handleSavedImgs}
              className='property-img-section'
              titleClassName='form-title'
              error={error[imgSection.type] && ERROR_LANG.atLeastOnePhotoRequired}
            />
          ))
        }
      </PolicyPropertyImgStyle>
    </CollapsibleCard>
  )
}

export default PolicyPropertyImg
