import get from 'lodash/get'
import moment from 'moment'
import { useCallback, useMemo, useState } from 'react'
import { KTP_IMG } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import InnerForm from '../../InnerForm'
import ImageGuideModal from '../../PolicyCustAgentForm/components/ImageGuideModal'
import ProvinceCityDropDown from '../../ProvinceCityDropDown'
import SingleImgContainer from '../../SingleImgContainer'
import { getPolicyCustomerData, getCustomerAddressFormData } from '../helper'
import { PolicyCustomerDataStyle } from './index.style'

function PolicyCustomerData (props) {
  // isMVApplication,
  const {
    applicationData = {}, onUpdateCustomerData, customerRef,
    customerAddressProvinceCityRef, customerAddressRef,
    onProvinceCitySubmit
  } = props
  const [imgModalState, setImgModalState] = useState({
    showImgModal: false
  })

  const applicationDate = get(applicationData, 'application_date', '')
  // TODO: Update to date of release
  const checkDate = moment('2021-04-22', 'YYYY-MM-DD')
  const isOldQuotation = moment(applicationDate, 'YYYY-MM-DD').isBefore(checkDate)
  const customerFormData = useMemo(() => getPolicyCustomerData({
    ...applicationData
  }, {
    border: true,
    className: 'remove-box-shadow',
    autoSearchInputClass: 'auto-search-input',
    uploadBtnClass: 'upload-wrapper'
  }, isOldQuotation), [applicationData, isOldQuotation])

  const customerAddressFormData = useMemo(() => getCustomerAddressFormData({
    ...applicationData
  }, {
    border: true,
    className: 'remove-box-shadow'
  }), [applicationData])

  const handleOpenImgModal = useCallback(() => {
    const imgContainer = (
      <SingleImgContainer
        title={LANG_STRINGS.photoKTP}
        imgUrl={KTP_IMG}
        titlePosition='up'
        titleAlign='start'
      />
    )
    setImgModalState({
      showImgModal: true,
      modalImgContainer: imgContainer,
      modalTitle: LANG_STRINGS.ktpPhotoGuide,
      modalBottomTitle: LANG_STRINGS.makeSureKTPPhotoClear
    })
  }, [])

  const handleCloseImgModal = useCallback(() => {
    setImgModalState({
      showImgModal: false
    })
    onUpdateCustomerData()
  }, [onUpdateCustomerData])

  const custAddRequired = get(applicationData, 'product.extra_details.customer_address_required', false)
  return (
    <CollapsibleCard title={LANG_STRINGS.customerData} isOpen>
      <PolicyCustomerDataStyle>
        <InnerForm
          formData={customerFormData}
          ref={customerRef}
          titleClassName='form-title'
          onGuideClick={handleOpenImgModal}
        />
        {
          custAddRequired &&
            <>
              <ProvinceCityDropDown
                onProvinceCitySubmit={onProvinceCitySubmit}
                ref={customerAddressProvinceCityRef}
                defaultData={{
                  province_code: get(applicationData, 'customer_data.customer_address.province_code', ''),
                  city_code: get(applicationData, 'customer_data.customer_address.city_code', '')
                }}
                showBorder
                titleClassName='form-title'
              />
              <InnerForm
                formData={customerAddressFormData}
                ref={customerAddressRef}
                titleClassName='form-title'
              />
            </>
        }
      </PolicyCustomerDataStyle>
      {
        imgModalState.showImgModal && (
          <ImageGuideModal
            showImgModal={imgModalState.showImgModal}
            title={imgModalState.modalTitle}
            onClose={handleCloseImgModal}
            modalImgContainer={imgModalState.modalImgContainer}
            bottomTitle={imgModalState.modalBottomTitle}
          />
        )
      }
    </CollapsibleCard>
  )
}

export default PolicyCustomerData
