import moment from 'moment'
import { dateAdd, formatDate, isDateValid } from '../../../../../helpers/formatDate'

export const parseDateFromApi = (date) => {
  if (!isDateValid(date, 'YYYY-MM-DD')) return ''
  const parsedDate = moment(date, 'YYYY-MM-DD', true) // API format is 'YYYY-MM-DD'
  return formatDate(parsedDate, 'DD/MM/YYYY') // User input format is 'DD/MM/YYYY'
}

export const formatDateToApi = (date) => {
  if (!isDateValid(date, 'DD/MM/YYYY')) return ''
  const parsedDate = moment(date, 'DD/MM/YYYY', true) // User input format is 'DD/MM/YYYY'
  return formatDate(parsedDate, 'YYYY-MM-DD') // API format is 'YYYY-MM-DD'
}

export const calculateEndDate = (startDate) => {
  const parsedStartDate = moment(startDate, 'DD/MM/YYYY', true)
  const endDate = dateAdd(parsedStartDate, 1, 'year')
  return formatDate(endDate, 'DD/MM/YYYY')
}

export const calculateSumInsured = (data) => {
  return (
    (data.building_value || 0) +
    (data.building_content_value || 0) +
    (data.equipment_value || 0) +
    (data.machine_value || 0) +
    (data.stock_value || 0)
  )
}
