import { useCallback } from 'react'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import Textarea from '../../Textarea'
import TitleError from '../../TitleError'

function PolicyPropertyData (props) {
  const { policyDetails = {}, errorField, onUpdateLocation } = props

  const handleInputChanges = useCallback((propertyAddress) => {
    onUpdateLocation(propertyAddress, 'propertyAddress')
  }, [onUpdateLocation])

  return (
    <CollapsibleCard title={LANG_STRINGS.insuredObject} isOpen>
      <div>
        <TitleError
          required
          weight={700}
          size='10px'
          title={LANG_STRINGS.locationOfRisk}
          error={errorField && LANG_STRINGS.required}
        />
        <Textarea
          errorField={errorField ? 'propertyRiskLocation' : ''}
          placeholder={LANG_STRINGS.enterRiskLocation}
          displayBorder
          name='propertyRiskLocation'
          className='remove-box-shadow'
          defaultValue={policyDetails.property_address}
          onChange={e => handleInputChanges(e.target.value)}
        />
      </div>
    </CollapsibleCard>
  )
}

export default PolicyPropertyData
