import { Upload } from '../..'
import { INPUT_FILE_TYPE } from '../../../constants/file'
import { DOCUMENT } from '../../../images'
import { LANG_STRINGS } from '../../../lang'
import CollapsibleCard from '../../CollapsibleCard'
import TitleError from '../../TitleError'

function PolicyCertificateAndAppointment(props) {
  const {
    error = {},
    isPhotoRequired,
    previousCertificateUrl,
    appointmentLetterUrl,
    onUpdate,
  } = props

  return (
    <>
      {!isPhotoRequired && (
        <CollapsibleCard title={LANG_STRINGS.policyCertificate} isOpen>
          <TitleError
            required
            weight={700}
            size="10px"
            title={LANG_STRINGS.policyPhotoCertificate}
            error={!!error.certificate && LANG_STRINGS.required}
          />
          <Upload
            label={LANG_STRINGS.policyPhotoCertificate}
            onUpload={(value) =>
              onUpdate(value.previous_certificate_url, 'previous_certificate_url')
            }
            name="previous_certificate_url"
            fileType={`${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`}
            hideLabel
            showImg
            icon={DOCUMENT}
            errorField={error.certificate && !previousCertificateUrl && 'previous_certificate_url'}
            defaultValue={previousCertificateUrl}
          />
        </CollapsibleCard>
      )}
      {appointmentLetterUrl && (
        <CollapsibleCard title={LANG_STRINGS.otherDocuments} isOpen>
          <TitleError
            weight={700}
            size="10px"
            title={LANG_STRINGS.letterOfAppointment}
            error={!!error.appointmentLetter && LANG_STRINGS.required}
          />
          <Upload
            onUpload={(value) => onUpdate(value.appointment_letter_url, 'appointment_letter_url')}
            name="appointment_letter_url"
            fileType={`${INPUT_FILE_TYPE.IMAGE},${INPUT_FILE_TYPE.PDF}`}
            hideLabel
            showImg
            icon={DOCUMENT}
            errorField={
              error.appointmentLetter && !appointmentLetterUrl && 'appointment_letter_url'
            }
            defaultValue={appointmentLetterUrl}
          />
        </CollapsibleCard>
      )}
    </>
  )
}

export default PolicyCertificateAndAppointment
